// Shared checks for "did someone commit something that belongs to their machine
// rather than to this repository?".
//
// The occasion for this module: a commit added a DSH latency baseline that had
// been generated by reading the local session store. It carried three absolute
// Windows paths, a Windows user name, and the titles of 24 sessions belonging to
// *other* projects. Nothing in the repository objected, because nothing was
// looking.
//
// The regexes capture only the first segment of a path. That is deliberate: a
// checkout path reports as its top directory, which is already enough to
// identify the leak, and a shorter match keeps the allowlist entries
// readable. An earlier attempt used /[A-Za-z]:\\\\/ and matched nothing in
// markdown, because that pattern only matches the double backslashes of a JSON
// string — a reminder that "zero hits" means "this regex found nothing", not
// "this file is clean".

// The character class excludes everything that shows up in a regular expression
// or a template literal (`\s*$`, `${broken.join(`), and the match must be at
// least two characters long, so `C:\\'` — a JS string holding a regex escape —
// is not reported as a drive path. Without this, the gate's first run reports
// three "paths" that are source code, and the allowlist starts out lying.
export const windowsPathPattern = /[A-Za-z]:\\+[^\s"\\,;'`$(){}*+[\]?|]{2,80}/g;
export const homePathPattern = /(?:\/home\/|\/Users\/)[A-Za-z0-9._-]{1,40}/g;

/**
 * True when the text looks like a dump of the DSH session store: a list of
 * sessions alongside the per-session prompts. Individual paths are a weaker
 * signal than this, because a session dump carries what the person was working
 * on in *other* repositories.
 */
export function looksLikeSessionDump(text) {
  return /"sessions"\s*:\s*\[/.test(text) && /"prompt"\s*:/.test(text);
}

/**
 * Scan one file's text. Returns the distinct matches per category, in first
 * appearance order, so a report can quote what was found without repeating it.
 */
export function scanText(text) {
  const windowsPaths = [...new Set(text.match(windowsPathPattern) ?? [])];
  const homePaths = [...new Set(text.match(homePathPattern) ?? [])];
  return { windowsPaths, homePaths, sessionDump: looksLikeSessionDump(text) };
}

export function isClean(result) {
  return (
    result.windowsPaths.length === 0 &&
    result.homePaths.length === 0 &&
    !result.sessionDump
  );
}

/**
 * An allowlist entry suppresses exactly one (path, kind, value) triple and must
 * carry a reason. Suppressing by path alone would blind the gate to everything
 * else in that file; suppressing by kind alone would blind it to every file.
 */
/**
 * The form an allowlist entry uses for a path: forward slashes, no leading
 * slash. An entry therefore never contains a string the scanner would match,
 * so the allowlist does not have to allowlist itself.
 */
export function canonicalPath(value) {
  return String(value).replace(/\\/g, '/').replace(/^\/+/, '');
}

export function applyAllowlist(file, result, allowlist) {
  const entries = (allowlist?.entries ?? []).filter(
    (entry) => entry.path === file,
  );
  const allowed = (kind, value) => {
    const wanted = canonicalPath(value);
    const hit = entries.find(
      (entry) => entry.kind === kind && canonicalPath(entry.value) === wanted,
    );
    return hit ? hit.reason : null;
  };

  const windowsPaths = [];
  const homePaths = [];
  const suppressed = [];

  for (const value of result.windowsPaths) {
    const reason = allowed('windowsPath', value);
    if (reason) suppressed.push({ kind: 'windowsPath', value, reason });
    else windowsPaths.push(value);
  }
  for (const value of result.homePaths) {
    const reason = allowed('homePath', value);
    if (reason) suppressed.push({ kind: 'homePath', value, reason });
    else homePaths.push(value);
  }

  let sessionDump = result.sessionDump;
  if (sessionDump) {
    const reason = allowed('sessionDump', true);
    if (reason) {
      suppressed.push({ kind: 'sessionDump', value: true, reason });
      sessionDump = false;
    }
  }

  return { windowsPaths, homePaths, sessionDump, suppressed };
}

/**
 * Turn a scan result into the lines a caller prints. Kept separate from the
 * scanning so the messages can be asserted without touching the filesystem.
 */
export function describeProblems(file, result) {
  const lines = [];
  for (const value of result.windowsPaths)
    lines.push(`${file}: machine path ${value}`);
  for (const value of result.homePaths)
    lines.push(`${file}: home directory ${value}`);
  if (result.sessionDump)
    lines.push(`${file}: looks like a dump of the local session store`);
  return lines;
}
